<?php
declare(strict_types=1); namespace Comfino\Common\Backend; use Comfino\Common\Backend\Log\LoggerFactory; use ComfinoExternal\Monolog\Logger as MonologLogger; class DebugLogger extends Logger{ private $logFilePath; private static $instance; private static $logger; public static function getInstance($logFilePath):self{if(self::$instance===null){self::$instance=new self($logFilePath);}return self::$instance;}private function __construct(string $logFilePath){$this->logFilePath=$logFilePath;} public function getLogger():MonologLogger{if(self::$logger===null){self::$logger=LoggerFactory::createDebugLogger($this->logFilePath);}return self::$logger;} public function logEvent($eventPrefix,$eventMessage,$parameters=null):void{$this->getLogger()->debug($eventPrefix.': '.$eventMessage,$parameters??[]);} public function getDebugLog($numLines):string{if(empty($this->logFilePath)){return'';}$actualLogPath=$this->findActualLogFile($this->logFilePath); if($actualLogPath===null||!file_exists($actualLogPath)){return'';}return implode('',FileUtils::readLastLines($actualLogPath,$numLines));} public function clearLogs():int{if($this->logFilePath===null){return 0;}return $this->clearLogFiles($this->logFilePath);}}